class Queue:
    def __init__(self):
        self._items = []

    @property
    def size(self):
        return len(self._items)

    def enqueue(self, value):
        self._items.append(value)

    def dequeue(self):
        return self._items.pop() if self._items else None  # 错误的实现：后进先出

    def peek(self):
        return self._items[-1] if self._items else None  # 错误的实现：查看的是队尾
